from pathlib import Path
import json,time
p=Path.home()/".local/state/prediction-project-executor/DEV-PRED-A2Z-R4P2-PREBUILD-POSTRESUME-VERIFY-20261007-N1E57.json"
deadline=time.time()+150
while time.time()<deadline:
    if p.is_file():
        try:
            o=json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            time.sleep(2); continue
        status=o.get("status")
        if status=="PASS":
            raise SystemExit(0)
        if status=="FAIL":
            err=str(o.get("error") or "")
            for rc in (11,12,30,31,32):
                if f"rc={rc}" in err:
                    raise SystemExit(rc)
            raise SystemExit(40)
    time.sleep(2)
raise SystemExit(21)
